function manageBreakpoints(){const rows=(state.project.settings.breakpoints||[]).map((b,i)=>`<div class="breakpoint-edit-row" data-bp-row="${i}"><input data-bp-k="label" value="${esc(b.label)}"><input data-bp-k="width" type="number" min="240" value="${b.width}"><button data-bp-del ${b.id==='base'?'disabled':''}>×</button></div>`).join('');const layer=modal('Responsive Breakpoints',`<div data-bp-list>${rows}</div><button data-bp-add>+ Breakpoint</button>`,()=>{mutate(()=>{const old=state.project.settings.breakpoints||[];const next=[];for(const row of $$('#modal-layer [data-bp-row]')){const idx=Number(row.dataset.bpRow),prior=old[idx]||{};next.push({id:prior.id||`bp-${Date.now().toString(36)}-${idx}`,label:row.querySelector('[data-bp-k="label"]').value||'Breakpoint',width:Math.max(240,Number(row.querySelector('[data-bp-k="width"]').value)||640)})}state.project.settings.breakpoints=next;if(!next.some(b=>b.id===state.breakpoint))state.breakpoint=next[0]?.id||'base'},'Updated breakpoints')});const list=layer.querySelector('[data-bp-list]');layer.querySelector('[data-bp-add]').onclick=()=>{const div=document.createElement('div');div.className='breakpoint-edit-row';div.dataset.bpRow=String(list.children.length);div.innerHTML='<input data-bp-k="label" value="Custom"><input data-bp-k="width" type="number" min="240" value="640"><button data-bp-del>×</button>';list.appendChild(div);div.querySelector('[data-bp-del]').onclick=()=>div.remove()};layer.querySelectorAll('[data-bp-del]').forEach(b=>b.onclick=()=>{if(!b.disabled)b.closest('[data-bp-row]').remove()})}
