const PROJECT_IMPORT_IGNORE=new Set(['node_modules','.git','dist','build','.astro','.svelte-kit','.next','.nuxt','coverage','.venv','venv','__pycache__']);
function supportedImportPath(name=''){const n=String(name).replace(/\\+/g,'/'),base=n.split('/').pop()||'';return /\.(astro|tsx?|jsx?|mjs|cjs|vue|svelte|html?|css|scss|sass|less|json|pyi?|c|h|cpp|hpp|qml|qmltypes|qmlproject|qrc)$/i.test(base)||['CMakeLists.txt','qmldir','qtquickcontrols2.conf'].includes(base)}
async function filesFromDirectoryHandle(handle){const out=[];let bytes=0;async function rec(dir,prefix=''){for await(const [name,child] of dir.entries()){if(PROJECT_IMPORT_IGNORE.has(name))continue;const rel=prefix?`${prefix}/${name}`:name;if(child.kind==='directory'){await rec(child,rel);continue}if(!supportedImportPath(rel))continue;const f=await child.getFile();if(f.size>2_000_000)continue;const content=await f.text();bytes+=content.length;if(bytes>24_000_000)throw new Error('Project import exceeds the 24 MB source snapshot limit.');out.push({filename:rel,content});if(out.length>=3000)throw new Error('Project import contains more than 3000 supported source files.')}}await rec(handle);return {name:handle.name||'Imported Project',files:out}}
function filesFromWebkitDirectory(){return new Promise((resolve,reject)=>{const input=document.createElement('input');input.type='file';input.multiple=true;input.webkitdirectory=true;input.setAttribute('webkitdirectory','');input.onchange=async()=>{try{const picked=[...(input.files||[])],out=[];let bytes=0;for(const f of picked){const rel=f.webkitRelativePath||f.name;if(rel.split('/').some(x=>PROJECT_IMPORT_IGNORE.has(x))||!supportedImportPath(rel)||f.size>2_000_000)continue;const content=await f.text();bytes+=content.length;if(bytes>24_000_000)throw new Error('Project import exceeds the 24 MB source snapshot limit.');out.push({filename:rel.split('/').slice(1).join('/')||f.name,content});if(out.length>=3000)throw new Error('Project import contains more than 3000 supported source files.')}const first=picked[0]?.webkitRelativePath?.split('/')[0]||'Imported Project';resolve({name:first,files:out})}catch(e){reject(e)}};input.click()})}
async function browseSnapshotProject(){if(window.showDirectoryPicker){try{const handle=await window.showDirectoryPicker({mode:'read'});return filesFromDirectoryHandle(handle)}catch(e){if(e?.name==='AbortError')return null;log(`Directory picker fallback: ${e.message}`)}}return filesFromWebkitDirectory()}
async function showProjectImportReview({analysis,files=null,name='Imported Project',live=false}){const rt=window.AstroUIDesignerRoundTrip;if(!rt)throw new Error('Round-trip bridge is not ready.');const adapters=await rt.adapters(),layer=$('#modal-layer'),mode=live?'Live workspace':'Read-only source snapshot';layer.innerHTML=`<div class="modal-backdrop"><div class="modal project-import-modal"><div class="modal-head"><span>Import Existing Project</span><button data-modal-close>×</button></div><div class="modal-body"><div class="project-import-hero"><strong>${esc(analysis.label||analysis.backend||'Unknown adapter')}</strong><span>${esc(mode)}</span></div><div class="modal-grid"><label>Project name</label><input data-import-name value="${esc(name)}"><label>Adapter</label><select data-import-backend>${adapters.filter(a=>a.operations?.import).map(a=>`<option value="${esc(a.id)}" ${a.id===analysis.backend?'selected':''}>${esc(a.label)} · ${esc(a.family)}</option>`).join('')}</select><label>Entry file</label><input data-import-entry value="${esc(analysis.entryFile||'')}"><label>Source files</label><div>${Number(analysis.files||files?.length||0)} (${Number(analysis.reachableFiles||0)} reachable)</div></div><div class="hint">${live?'The selected folder stays connected to the workspace API, so reviewed source round-trip patches can be written back to disk.':'The browser imported a source snapshot. Visual editing and cross-framework export work normally, but source write-back requires opening the folder as a live workspace.'}</div><div class="project-import-capabilities"><strong>Adapter capabilities</strong><ul>${(analysis.capabilities?.supported||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><div data-import-status class="hint"></div></div><div class="modal-actions"><button data-modal-close>Cancel</button><button data-import-confirm class="primary">Import project</button></div></div></div>`;layer.querySelectorAll('[data-modal-close]').forEach(b=>b.onclick=()=>layer.innerHTML='');const status=layer.querySelector('[data-import-status]');layer.querySelector('[data-import-confirm]').onclick=async()=>{const btn=layer.querySelector('[data-import-confirm]'),backend=layer.querySelector('[data-import-backend]').value,entryFile=layer.querySelector('[data-import-entry]').value.trim(),projectName=layer.querySelector('[data-import-name]').value.trim()||name;btn.disabled=true;status.textContent='Importing and building source mappings…';try{const result=live?await rt.importWorkspace({backend,entryFile,name:projectName}):await rt.importFiles(files,{backend,entryFile,name:projectName});layer.innerHTML='';log(`Imported ${result.label||result.backend}: ${result.files} files · ${result.nodes} root node(s)`);openBottomTab('roundtrip')}catch(e){status.textContent=`Import failed: ${e.message}`;btn.disabled=false}}}
async function importExistingProject(){const rt=window.AstroUIDesignerRoundTrip;if(!rt)return alert('Round-trip project import is still initializing.');try{if(state.workspaceApi){try{const scan=await browseWorkspace(state.project.workspace?.rootPath||'');if(scan?.canceled)return null;if(scan&&scan.rootPath){state.project.workspace.rootPath=scan.rootPath;state.project.workspace.files=(scan.files||[]).map(workspaceFileRow);state.project.workspace.lastScan=new Date().toISOString();const analysis=await rt.detectWorkspace();return showProjectImportReview({analysis,name:scan.rootPath.split(/[\\/]/).filter(Boolean).at(-1)||'Imported Project',live:true})}}catch(e){log(`Native project browser unavailable: ${e.message}`)}}const picked=await browseSnapshotProject();if(!picked||!picked.files.length)return;const analysis=await rt.analyzeFiles(picked.files);if(!analysis.ok)throw new Error(analysis.message);return showProjectImportReview({analysis,files:picked.files,name:picked.name,live:false})}catch(e){alert(`Project import failed: ${e.message}`);log(`Project import failed: ${e.message}`)}}
function undoProject(){if(!state.history.length)return;state.future.push(JSON.stringify(state.project));state.project=JSON.parse(state.history.pop());normalizeProject();ensureHotkeySettings();renderAll();log('Undo')}
function redoProject(){if(!state.future.length)return;state.history.push(JSON.stringify(state.project));state.project=JSON.parse(state.future.pop());normalizeProject();ensureHotkeySettings();renderAll();log('Redo')}
function copySelected(){state.clipboard=deepClone(selected());log(`Copied ${selected().name}`)}
function cutSelected(){if(selected().id===root().id)return;state.clipboard=deepClone(selected());mutate(()=>{removeNode(root(),selected().id);state.selectedId=root().id},'Cut node')}
function pasteSelected(){if(!state.clipboard)return;let parent=selected();if(!COMPONENTS[parent.type]?.acceptsChildren)parent=findParent(root(),parent.id)||root();mutate(()=>{const n=deepClone(state.clipboard);walk(n,x=>{x.id=`${x.type}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,6)}`;for(const a of x.actions||[])a.id=`act-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,6)}`});parent.children.push(n);state.selectedId=n.id},'Pasted node')}
function duplicateSelected(){if(selected().id===root().id)return;mutate(()=>{const n=duplicateNode(root(),selected().id);if(n)state.selectedId=n.id},'Duplicated node')}
function deleteSelected(){if(selected().id===root().id)return;const n=selected();mutate(()=>{const parent=findParent(root(),n.id);removeNode(root(),n.id);state.selectedId=parent?.id||root().id},`Deleted ${n.name}`)}
function moveSibling(delta){const n=selected(),p=findParent(root(),n.id);if(!p)return;const i=p.children.findIndex(x=>x.id===n.id),j=Math.max(0,Math.min(p.children.length-1,i+delta));if(i===j)return;mutate(()=>{p.children.splice(i,1);p.children.splice(j,0,n)},delta<0?'Moved node up':'Moved node down')}
function wrapSelected(type){const n=selected(),p=findParent(root(),n.id);if(!p)return;mutate(()=>{const i=p.children.findIndex(x=>x.id===n.id),w=createNode(type,{name:type==='row'?'WrappedRow':'WrappedColumn'});p.children.splice(i,1,w);w.children.push(n);state.selectedId=w.id},`Wrapped in ${type}`)}
function freeformSelectionNodes(){const n=selected(),p=findParent(root(),n.id);if(!p||p.type!=='freeform')return[];return p.children||[]}
function alignSelection(mode){const nodes=freeformSelectionNodes();if(nodes.length<2)return log('Align requires children in a Freeform Layer.');const rect=n=>({n,left:parseFloat(n.style?.base?.left)||0,top:parseFloat(n.style?.base?.top)||0,width:parseFloat(n.style?.base?.width)||100,height:parseFloat(n.style?.base?.height)||40}),r=nodes.map(rect);mutate(()=>{if(mode==='left'){const v=Math.min(...r.map(x=>x.left));r.forEach(x=>x.n.style.base.left=`${v}px`)}if(mode==='right'){const v=Math.max(...r.map(x=>x.left+x.width));r.forEach(x=>x.n.style.base.left=`${v-x.width}px`)}if(mode==='hcenter'){const v=r.reduce((a,x)=>a+x.left+x.width/2,0)/r.length;r.forEach(x=>x.n.style.base.left=`${v-x.width/2}px`)}if(mode==='top'){const v=Math.min(...r.map(x=>x.top));r.forEach(x=>x.n.style.base.top=`${v}px`)}if(mode==='bottom'){const v=Math.max(...r.map(x=>x.top+x.height));r.forEach(x=>x.n.style.base.top=`${v-x.height}px`)}if(mode==='vcenter'){const v=r.reduce((a,x)=>a+x.top+x.height/2,0)/r.length;r.forEach(x=>x.n.style.base.top=`${v-x.height/2}px`)}},`Aligned ${mode}`)}
function distributeSelection(axis){const nodes=freeformSelectionNodes();if(nodes.length<3)return log('Distribute requires 3+ children in a Freeform Layer.');const r=nodes.map(n=>({n,left:parseFloat(n.style?.base?.left)||0,top:parseFloat(n.style?.base?.top)||0,width:parseFloat(n.style?.base?.width)||100,height:parseFloat(n.style?.base?.height)||40})).sort((a,b)=>axis==='h'?a.left-b.left:a.top-b.top);mutate(()=>{if(axis==='h'){const start=r[0].left,end=r.at(-1).left+r.at(-1).width,total=r.reduce((a,x)=>a+x.width,0),gap=(end-start-total)/(r.length-1);let pos=start;r.forEach(x=>{x.n.style.base.left=`${pos}px`;pos+=x.width+gap})}else{const start=r[0].top,end=r.at(-1).top+r.at(-1).height,total=r.reduce((a,x)=>a+x.height,0),gap=(end-start-total)/(r.length-1);let pos=start;r.forEach(x=>{x.n.style.base.top=`${pos}px`;pos+=x.height+gap})}},`Distributed ${axis}`)}
function inferSelectedLayout(){const n=selected();if(!COMPONENTS[n.type]?.acceptsChildren||(n.children||[]).length<2)return alert('Select a container with at least two children.');const pts=n.children.map(c=>({c,x:parseFloat(c.style?.base?.left)||0,y:parseFloat(c.style?.base?.top)||0})),xs=pts.map(p=>p.x),ys=pts.map(p=>p.y),horizontal=(Math.max(...xs)-Math.min(...xs))>=(Math.max(...ys)-Math.min(...ys));mutate(()=>{n.style.base.display='flex';n.style.base.flexDirection=horizontal?'row':'column';n.style.base.gap=n.style.base.gap||'16px';for(const c of n.children)for(const k of ['position','left','right','top','bottom'])delete c.style.base[k]},`Inferred ${horizontal?'row':'column'} layout`)}
function fitCanvas(){const shell=$('#artboard-shell'),w=Math.max(320,(shell?.clientWidth||1000)-60);state.zoom=Math.min(1.4,Math.max(.25,w/(activeBreakpoint().width||1280)));renderCanvas()}
function createActivePage(){workbenches.pageEditor()}
function deleteActivePage(){if(state.doc.kind!=='page')return alert('Open a page document first.');workbenches.deletePageUi(state.doc.id)}
function sourceAwareSave(){if(state.sourceFile&&['split','code'].includes(state.mode)&&document.activeElement===$('#source-editor'))return $('#source-apply-btn').click();saveProject()}
