function executeCommand(id){const cmd=commandDefinitions().find(c=>c.id===id);if(!cmd)return false;try{cmd.run?.();return true}catch(err){log(`Command ${id} failed: ${err.message}`);alert(err.message);return false}}
function currentHotkeyMap(){return effectiveHotkeys(commandDefinitions(),ensureHotkeySettings())}
function setCommandBinding(commandId,binding,{append=false}={}){const cmds=commandDefinitions(),current=currentHotkeyMap(),normalized=normalizeHotkey(binding);if(!normalized)return false;for(const [otherId,bindings] of Object.entries(current)){if(otherId===commandId||!bindings.includes(normalized))continue;const other=cmds.find(c=>c.id===otherId);if(!confirm(`${normalized} is currently assigned to “${other?.label||otherId}”.\n\nMove it to the new command?`))return false;const remaining=bindings.filter(b=>b!==normalized);state.project.editor.hotkeys=setHotkeyOverride(state.project.editor.hotkeys,otherId,remaining)}const next=append?[...(current[commandId]||[]).filter(b=>b!==normalized),normalized]:[normalized];state.project.editor.hotkeys=setHotkeyOverride(state.project.editor.hotkeys,commandId,next);persistHotkeys();state.dirty=true;renderDockPanelByKey('bottom:hotkeys');return true}
function renderHotkeysPanel(box){ensureHotkeySettings();const commands=commandDefinitions(),map=currentHotkeyMap(),conflicts=findHotkeyConflicts(map),conflictBindings=new Set(conflicts.map(c=>c.binding)),query=state.hotkeySearch||'';const rows=commands.filter(c=>!query||`${c.category} ${c.label} ${c.description||''} ${c.id}`.toLowerCase().includes(query.toLowerCase()));box.innerHTML=`<div class="workbench-toolbar"><strong>Keyboard Shortcuts</strong><input data-hotkey-search placeholder="Filter commands…" value="${esc(query)}"><button data-hotkey-export>Export</button><button data-hotkey-import-btn>Import</button><button data-hotkey-reset-all>Reset all</button><input data-hotkey-import type="file" accept=".json" hidden></div><div class="hint">Shortcuts are stored in the project and mirrored to local preferences. Every relocatable panel is also a command, so frequently used tabs can get direct shortcuts.</div>${state.hotkeyCaptureCommand?`<div class="hotkey-capture-banner">${state.hotkeyCaptureAppend?'Add another shortcut to':'Press the new shortcut for'} <strong>${esc(commands.find(c=>c.id===state.hotkeyCaptureCommand)?.label||state.hotkeyCaptureCommand)}</strong>. Escape cancels; Backspace clears.</div>`:''}<table class="data-table hotkey-table"><thead><tr><th>Command</th><th>Shortcut</th><th>Default</th><th></th></tr></thead><tbody>${rows.map(c=>{const bindings=map[c.id]||[],custom=Object.prototype.hasOwnProperty.call(state.project.editor.hotkeys,c.id);return `<tr data-command="${esc(c.id)}"><td><strong>${esc(c.label)}</strong><small>${esc(c.category)} · ${esc(c.id)}</small></td><td>${bindings.map(b=>`<kbd class="${conflictBindings.has(b)?'conflict':''}">${esc(hotkeyLabel(b,navigator.platform||''))}</kbd>`).join(' ')||'<span class="muted">Unassigned</span>'}</td><td>${(c.defaultBindings||[]).map(b=>`<kbd>${esc(hotkeyLabel(b,navigator.platform||''))}</kbd>`).join(' ')}</td><td><button data-hotkey-edit="${esc(c.id)}">Change</button><button data-hotkey-add="${esc(c.id)}">+ Alt</button><button data-hotkey-clear="${esc(c.id)}">Clear</button>${custom?`<button data-hotkey-reset="${esc(c.id)}">Reset</button>`:''}</td></tr>`}).join('')}</tbody></table>${conflicts.length?`<div class="hint audit-error">Conflicts: ${conflicts.map(c=>`${esc(c.binding)} → ${c.commandIds.map(id=>esc(commands.find(x=>x.id===id)?.label||id)).join(', ')}`).join('; ')}</div>`:''}`;box.querySelector('[data-hotkey-search]').oninput=x=>{state.hotkeySearch=x.target.value;renderHotkeysPanel(box)};box.querySelectorAll('[data-hotkey-edit]').forEach(b=>b.onclick=()=>{state.hotkeyCaptureCommand=b.dataset.hotkeyEdit;state.hotkeyCaptureAppend=false;renderHotkeysPanel(box)});box.querySelectorAll('[data-hotkey-add]').forEach(b=>b.onclick=()=>{state.hotkeyCaptureCommand=b.dataset.hotkeyAdd;state.hotkeyCaptureAppend=true;renderHotkeysPanel(box)});box.querySelectorAll('[data-hotkey-clear]').forEach(b=>b.onclick=()=>{state.project.editor.hotkeys=setHotkeyOverride(state.project.editor.hotkeys,b.dataset.hotkeyClear,[]);persistHotkeys();state.dirty=true;renderHotkeysPanel(box)});box.querySelectorAll('[data-hotkey-reset]').forEach(b=>b.onclick=()=>{state.project.editor.hotkeys=clearHotkeyOverride(state.project.editor.hotkeys,b.dataset.hotkeyReset);persistHotkeys();state.dirty=true;renderHotkeysPanel(box)});box.querySelector('[data-hotkey-reset-all]').onclick=()=>{if(confirm('Reset all keyboard shortcuts to defaults?')){state.project.editor.hotkeys={};persistHotkeys();state.dirty=true;renderHotkeysPanel(box)}};box.querySelector('[data-hotkey-export]').onclick=()=>downloadInterchangeArtifact('astro-ui-designer-hotkeys.json',JSON.stringify({format:'astro-ui-hotkeys',version:1,overrides:state.project.editor.hotkeys},null,2)+'\n','application/json');const picker=box.querySelector('[data-hotkey-import]');box.querySelector('[data-hotkey-import-btn]').onclick=()=>picker.click();picker.onchange=async()=>{const file=picker.files?.[0];if(!file)return;try{const doc=JSON.parse(await file.text()),raw=doc?.format==='astro-ui-hotkeys'?doc.overrides:doc;if(!raw||typeof raw!=='object'||Array.isArray(raw))throw new Error('Expected a hotkey override object.');const ids=new Set(commands.map(c=>c.id)),next={};for(const [id,value] of Object.entries(raw)){if(!ids.has(id))continue;const vals=(Array.isArray(value)?value:[value]).map(normalizeHotkey).filter(Boolean);next[id]=[...new Set(vals)]}state.project.editor.hotkeys=next;persistHotkeys();state.dirty=true;renderHotkeysPanel(box)}catch(err){alert(`Hotkey import failed: ${err.message}`)}finally{picker.value=''}}}
function handleGlobalKeydown(ev){if(state.hotkeyCaptureCommand){ev.preventDefault();ev.stopPropagation();if(ev.key==='Escape'){state.hotkeyCaptureCommand='';state.hotkeyCaptureAppend=false;renderDockPanelByKey('bottom:hotkeys');return}if(['Backspace','Delete'].includes(ev.key)&&!ev.ctrlKey&&!ev.altKey&&!ev.metaKey){state.project.editor.hotkeys=setHotkeyOverride(ensureHotkeySettings(),state.hotkeyCaptureCommand,[]);state.hotkeyCaptureCommand='';state.hotkeyCaptureAppend=false;persistHotkeys();state.dirty=true;renderDockPanelByKey('bottom:hotkeys');return}const binding=eventToHotkey(ev);if(!binding||['Ctrl','Alt','Shift','Meta'].includes(binding))return;const id=state.hotkeyCaptureCommand,append=Boolean(state.hotkeyCaptureAppend);state.hotkeyCaptureCommand='';state.hotkeyCaptureAppend=false;setCommandBinding(id,binding,{append});return}if(ev.key==='Escape'){$('#modal-layer').innerHTML='';$('#popover-layer').innerHTML='';return}const hit=commandForEvent(ev,commandDefinitions(),ensureHotkeySettings());if(hit&&shouldHandleHotkey(ev,hit.command)){ev.preventDefault();executeCommand(hit.command.id)}}
