function dockInsertionIndex(strip,clientX){const buttons=[...strip.querySelectorAll('button[data-dock-panel]')].filter(x=>x.dataset.dockPanel!==dockState.dragKey);for(let i=0;i<buttons.length;i++){const r=buttons[i].getBoundingClientRect();if(clientX<r.left+r.width/2)return{index:i,before:buttons[i]}}return{index:buttons.length,before:null}}
