function moveDockPanelUi(key,zone,index=Infinity){dockState.layout=moveDockPanelModel(dockState.layout,key,zone,index);if(zone==='bottom'){state.bottomExpanded=true;$('#app').classList.remove('bottom-minimized');$('#bottom-toggle-btn').textContent='⌄'}persistDockLayout();applyDockLayoutDom();return true}
