function resetDockLayoutUi(){dockState.layout=defaultDockLayout(dockState.registry);state.bottomExpanded=false;$('#app').classList.add('bottom-minimized');$('#bottom-toggle-btn').textContent='⌃';persistDockLayout();applyDockLayoutDom();return true}
